import os
import re

WRITE_INDICATORS = [
    "create_",
    "update_",
    "delete_",
    "save_",
    "write_",
    "POST",
    "PUT",
    "PATCH",
    "'created': True",
    "'updated': True",
    "'deleted': True",
]


def find_function_bounds(lines: list[str], call_line: int) -> tuple[int, int]:
    """Return start/end line indices for the function containing call_line."""
    start = 0
    for i in range(call_line, -1, -1):
        if lines[i].startswith("def "):
            start = i
            break
    end = len(lines)
    for i in range(call_line + 1, len(lines)):
        if lines[i].startswith("def "):
            end = i
            break
    return start, end


def is_write_scope(lines: list[str], call_line: int) -> bool:
    func_start, func_end = find_function_bounds(lines, call_line)
    body = "\n".join(lines[func_start:func_end])
    return any(ind in body for ind in WRITE_INDICATORS)


def migrate_file(path: str) -> None:
    with open(path, "r") as fh:
        content = fh.read()

    if "legacy_auth" not in content:
        return

    lines = content.split("\n")
    new_lines = []
    changed = False
    for idx, line in enumerate(lines):
        new_line = line
        if "from app.auth import legacy_auth" in line:
            new_line = line.replace("legacy_auth", "new_auth")
            changed = True
        elif "legacy_auth(" in line:
            scope = "write" if is_write_scope(lines, idx) else "read"
            new_line = re.sub(
                r"legacy_auth\(([^)]+)\)",
                rf'new_auth(\1, scope="{scope}")',
                line,
            )
            changed = True
        new_lines.append(new_line)

    if changed:
        with open(path, "w") as fh:
            fh.write("\n".join(new_lines))
        print(f"migrated {path}")


def main() -> None:
    root = "app"
    for dirpath, _dirnames, filenames in os.walk(root):
        for fname in filenames:
            if not fname.endswith(".py"):
                continue
            path = os.path.join(dirpath, fname)
            # Keep app/auth.py untouched (definition must remain)
            if os.path.samefile(path, os.path.join(root, "auth.py")):
                continue
            migrate_file(path)


if __name__ == "__main__":
    main()
